        n = max(max(u, v) for u, v in edges) + 1
        T = [[-math.inf] * n for _ in range(n)]
        for u, v in edges:
            T[u][v] = 0
            T[v][u] = 0
        return T

    def rank(T):
        n = len(T)
        M = [row[:] for row in T]
        pivot_row = 0
        for col in range(n):
            max_row = pivot_row
            for i in range(pivot_row, n):
                if abs(M[i][col]) > abs(M[max_row][col]):
                    max_row = i
            M[pivot_row], M[max_row] = M[max_row], M[pivot_row]
